const G_CAN_DBI = 2.15; // the whip on the can

const G_YAGI_DBI = 7.5;
const G_STOCK_DBI = 2.15; // the XBee's stock whip

const RATE_FAST_KBPS = 200;
const RATE_SLOW_KBPS = 10;
const SENS_FAST_DBM = -101;
const SENS_SLOW_DBM = -110;

const LOSS_DB = 1.5; // coax, SMA pigtail and connectors
const FADE_DB = 20; // reserve held back for fades, marked on the meter
const FIELD_KM = 4.2; // stable link in the field test
const D_MIN_KM = 0.1;
const D_MAX_KM = 10;
const STOPS_KM = [0.1, 0.5, 1, 2, 4.2, 10];

const METER_LOW = -120;
const METER_HIGH = -30;

const gainOf = (yagi = 1) => G_STOCK_DBI + (G_YAGI_DBI - G_STOCK_DBI) * yagi;
const sensOf = (slow = 0) => SENS_FAST_DBM + (SENS_SLOW_DBM - SENS_FAST_DBM) * slow;

