const rxDbm = (km, gain = G_YAGI_DBI) => TX_DBM + G_CAN_DBI + gain - fsplDb(km) - LOSS_DB;
const marginDb = (km, gain = G_YAGI_DBI, sens = SENS_FAST_DBM) => rxDbm(km, gain) - sens;

