const rateText = (slow) => (slow ? `${RATE_SLOW_KBPS} kb/s · hears ${signed(SENS_SLOW_DBM)} dBm` : `${RATE_FAST_KBPS} kb/s · hears ${signed(SENS_FAST_DBM)} dBm`);

